package Controllers; import Services.OrderService; import java.io.*; import javax.servlet.annotation.WebServlet; import javax.servlet.http.*;
@WebServlet("/CancelOrderServlet") public class CancelOrderServlet extends HttpServlet{private final OrderService s=new OrderService();protected void doPost(HttpServletRequest r,HttpServletResponse p)throws IOException{s.cancel(Integer.parseInt(r.getParameter("id")));p.sendRedirect("ViewOrderHistoryServlet");}}
